import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose2d_cute_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int64_t stride_h, int64_t stride_w,
                                            int64_t pad_h, int64_t pad_w,
                                            int64_t dil_h, int64_t dil_w,
                                            int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ int floor_div_i32(int a, int b) {
  return a >= 0 ? a / b : -((-a + b - 1) / b);
}
template <int BC, int CC, int THREADS>
__global__ void __launch_bounds__(THREADS, 3) conv_transpose2d_grouped_cute_kernel(
    const float* __restrict__ Xp,
    const float* __restrict__ Wp,
    const float* __restrict__ Bp,
    float* __restrict__ Yp,
    int N, int Cin, int H, int Win,
    int Cout, int Hout, int Wout,
    int KH, int KW,
    int sh, int sw, int ph, int pw, int dh, int dw,
    int groups, int icg, int ocg,
    int tiles_per_group, int num_w_tiles)
{
  constexpr int TX = 16;
  constexpr int TY = 16;
  constexpr int TW = TX;  // block output tile is TY x (2*TW); each thread owns 2 columns
  static_assert(THREADS == TX * TY, "THREADS must be 16*16");
  static_assert(CC % 4 == 0, "CC must be a multiple of 4 for float4 shared loads");
  const int tid = threadIdx.x;
  const int tx = tid & (TX - 1);
  const int ty = tid >> 4;
  const int n = blockIdx.z;
  const int by = blockIdx.y;
  const int g  = by / tiles_per_group;
  const int ct = by - g * tiles_per_group;
  const int group_co_begin = g * ocg;
  const int group_co_end   = min(group_co_begin + ocg, Cout);
  const int co0 = group_co_begin + ct * BC;
  const int ci0 = g * icg;
  const int spatial_tile = blockIdx.x;
  const int th = spatial_tile / num_w_tiles;
  const int tw = spatial_tile - th * num_w_tiles;
  const int h0 = th * TY;
  const int w0 = tw * (2 * TW);
  const int ho = h0 + ty;
  const int wo0 = w0 + tx;
  const int wo1 = wo0 + TX;
  const bool col_valid0 = (ho < Hout) && (wo0 < Wout);
  const bool col_valid1 = (ho < Hout) && (wo1 < Wout);
  // Two-column register blocking: each staged weight float4 feeds eight FMAs.
  // Conservative exact input footprint for this TY x (2*TW) output tile.
  const int hend = min(h0 + TY, Hout) - 1;
  const int wend = min(w0 + 2 * TW, Wout) - 1;
  const int hnum_lo = h0 + ph - (KH - 1) * dh;
  const int hnum_hi = hend + ph;
  int hi_lo = max(0, floor_div_i32(hnum_lo, sh));
  int hi_hi = min(H - 1, floor_div_i32(hnum_hi, sh));
  if (hi_hi < hi_lo) { hi_lo = 0; hi_hi = -1; }
  const int wnum_lo = w0 + pw - (KW - 1) * dw;
  const int wnum_hi = wend + pw;
  int wi_lo = max(0, floor_div_i32(wnum_lo, sw));
  int wi_hi = min(Win - 1, floor_div_i32(wnum_hi, sw));
  if (wi_hi < wi_lo) { wi_lo = 0; wi_hi = -1; }
  const int in_h = hi_hi - hi_lo + 1;
  const int in_w = wi_hi - wi_lo + 1;
  const int in_plane = in_h * in_w;
  // CuTe global tensors.
  Tensor mX = make_tensor(
      make_gmem_ptr(Xp),
      make_shape(N, Cin, H, Win),
      make_stride((int64_t)Cin * H * Win, (int64_t)H * Win, (int64_t)Win, Int<1>{})
  );
  Tensor mY = make_tensor(
      make_gmem_ptr(Yp),
      make_shape(N, Cout, Hout, Wout),
      make_stride((int64_t)Cout * Hout * Wout, (int64_t)Hout * Wout, (int64_t)Wout, Int<1>{})
  );
  // PyTorch ConvTranspose2d weight layout: [Cin, Cout/groups, KH, KW]
  Tensor mW = make_tensor(
      make_gmem_ptr(Wp),
      make_shape(Cin, ocg, KH, KW),
      make_stride((int64_t)ocg * KH * KW, (int64_t)KH * KW, (int64_t)KW, Int<1>{})
  );
  const int K = KH * KW;
  const int w_elems = BC * CC * K;
  extern __shared__ float smem_raw[];
  float* sW_raw = smem_raw;
  float* sX_raw = smem_raw + w_elems;
  // Channel-fastest weight tile: sW(bc, k, cc) keeps the CC dimension contiguous
  // so the hot accumulation loop can fetch four channels per float4 shared load.
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<BC>{}, K, Int<CC>{}),
      make_stride(K * CC, CC, Int<1>{})
  );
  // Stage the reusable input activation tile for the current input-channel chunk.
  auto sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(in_h, in_w, Int<CC>{}),
      make_stride(in_w * CC, CC, Int<1>{})
  );
  // Register blocking over two output columns per thread, plus vectorized float4
  // shared-memory loads across the channel chunk: every staged weight vector now
  // feeds eight FMAs, halving shared-load issue pressure per FMA.
  float acc0[BC];
  float acc1[BC];
  const int bc_valid = min(BC, group_co_end - co0);
  #pragma unroll
  for (int bc = 0; bc < BC; ++bc) {
    const int co = co0 + bc;
    const float bv = (bc < bc_valid && Bp != nullptr) ? Bp[co] : 0.0f;
    acc0[bc] = bv;
    acc1[bc] = bv;
  }
  for (int cchunk = 0; cchunk < icg; cchunk += CC) {
    const int cc_valid = min(CC, icg - cchunk);
