    // loads stay coalesced, then store into the channel-fast shared tile.
    const int x_total = CC * in_plane;
    for (int idx = tid; idx < x_total; idx += THREADS) {
      const int cc = idx / in_plane;
      const int rem = idx - cc * in_plane;
      const int ih = rem / in_w;
      const int iw = rem - ih * in_w;
      float v = 0.0f;
