      // with 0 <= mh < sh, so ah is valid iff mh == 0 and 0 <= hi_r < H.
      int hi_r = floor_div_i32(ho + ph, sh);
      int mh = (ho + ph) - hi_r * sh;
      for (int kh = 0; kh < KH; ++kh) {
        const bool row_ok = (mh == 0) && ((unsigned)hi_r < (unsigned)H);
