        // Column state at kw = 0: aw = wo + pw - kw*dw, kept as aw = wi*sw + mw
        // with 0 <= mw < sw. This is independent of kh, but the incremental
        // update is only a few integer ops, so restarting it per row is cheap.
        int wi0_r = floor_div_i32(wo0 + pw, sw);
        int mw0 = (wo0 + pw) - wi0_r * sw;
        int wi1_r = floor_div_i32(wo1 + pw, sw);
        int mw1 = (wo1 + pw) - wi1_r * sw;
        for (int kw = 0; kw < KW; ++kw) {
          const int k = kh * KW + kw;
          const bool ok0 = col_valid0 && row_ok && (mw0 == 0) &&
                           ((unsigned)wi0_r < (unsigned)Win);
          const bool ok1 = col_valid1 && row_ok && (mw1 == 0) &&
                           ((unsigned)wi1_r < (unsigned)Win);
          const int iw0 = wi0_r - wi_lo;
          const int iw1 = wi1_r - wi_lo;
          if (ok0 || ok1) {
            // sX and sW are zero-filled beyond cc_valid/bc_valid, so the channel
            // chunk can be swept unconditionally with vectorized float4 loads.
            #pragma unroll
            for (int cc4 = 0; cc4 < CC; cc4 += 4) {
              const float4 xv0 = ok0 ? *reinterpret_cast<const float4*>(&sX(ih, iw0, cc4))
