                acc0[bc] += xv0.y * wv.y;
                acc0[bc] += xv0.z * wv.z;
                acc0[bc] += xv0.w * wv.w;
                acc1[bc] += xv1.x * wv.x;
                acc1[bc] += xv1.y * wv.y;
                acc1[bc] += xv1.z * wv.z;
                acc1[bc] += xv1.w * wv.w;
