  const int64_t ocg = w_c.size(1);
  const int64_t Cout = ocg * groups;
  const int64_t KH = w_c.size(2);
  const int64_t KW = w_c.size(3);
  TORCH_CHECK(Cout % groups == 0, "Cout must be divisible by groups");

  torch::Tensor b_c;
