      <<<grid, block, smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          b_ptr,
          y.data_ptr<float>(),
          (int)N, (int)Cin, (int)H, (int)Win,
          (int)Cout, (int)Hout, (int)Wout,
          (int)KH, (int)KW,
          (int)stride_h, (int)stride_w, (int)pad_h, (int)pad_w, (int)dil_h, (int)dil_w,
          (int)groups, (int)icg, (int)ocg,
