  // Maximum input footprint needed by any 16x64 output tile. The +3 term is a
  // conservative guard for floor division and edge effects; actual per-block tiles are clamped.
  int64_t in_tile_h_max = ((int64_t)15 + dil_h * (KH - 1)) / stride_h + 3;
  int64_t in_tile_w_max = ((int64_t)63 + dil_w * (KW - 1)) / stride_w + 3;
  if (in_tile_h_max > H) in_tile_h_max = H;
  if (in_tile_w_max > Win) in_tile_w_max = Win;
  auto y = torch::empty({N, Cout, Hout, Wout}, x_c.options());
